			matchUrl: environment.OPENAI_BASE_URL ?? "https://api.openai.com/v1",
			matchHeaders: { Authorization: `Bearer ${sandboxEnvironment.OPENAI_API_KEY}` },
			transformHeaders: { Authorization: `Bearer ${environment.OPENAI_API_KEY}` }
		})] : [];
		case "anthropic": {
			const matchUrl = environment.ANTHROPIC_BASE_URL ?? "https://api.anthropic.com";
			const transformations = [];
			if (environment.ANTHROPIC_API_KEY != null && sandboxEnvironment.ANTHROPIC_API_KEY != null) transformations.push(createCredentialRequestTransformation({
				matchUrl,
				matchHeaders: { "x-api-key": sandboxEnvironment.ANTHROPIC_API_KEY },
				transformHeaders: { "x-api-key": environment.ANTHROPIC_API_KEY }
			}));
			if (environment.ANTHROPIC_AUTH_TOKEN != null && sandboxEnvironment.ANTHROPIC_AUTH_TOKEN != null) transformations.push(createCredentialRequestTransformation({
				matchUrl,
				matchHeaders: { Authorization: `Bearer ${sandboxEnvironment.ANTHROPIC_AUTH_TOKEN}` },
				transformHeaders: { Authorization: `Bearer ${environment.ANTHROPIC_AUTH_TOKEN}` }
			}));
			return transformations;
		}
		case "google": return environment.GOOGLE_GENERATIVE_AI_API_KEY && sandboxEnvironment.GOOGLE_GENERATIVE_AI_API_KEY ? [createCredentialRequestTransformation({
			matchUrl: "https://generativelanguage.googleapis.com",
			matchHeaders: { "x-goog-api-key": sandboxEnvironment.GOOGLE_GENERATIVE_AI_API_KEY },
			transformHeaders: { "x-goog-api-key": environment.GOOGLE_GENERATIVE_AI_API_KEY }
		})] : [];
		case "xai": return createBearerTransformation({
			environment,
			sandboxEnvironment,
			environmentVariableName: "XAI_API_KEY",
			matchUrl: environment.XAI_BASE_URL ?? "https://api.x.ai/v1"
