		case "github-copilot": return createBearerTransformation({
			environment,
			sandboxEnvironment,
			environmentVariableName: environment.GITHUB_COPILOT_TOKEN != null ? "GITHUB_COPILOT_TOKEN" : "GITHUB_TOKEN",
			matchUrl: "https://api.githubcopilot.com"
		});
		case "poe": return createBearerTransformation({
			environment,
			sandboxEnvironment,
			environmentVariableName: "POE_API_KEY",
			matchUrl: "https://api.poe.com"
		});
		case "opencode-go": return createBearerTransformation({
			environment,
			sandboxEnvironment,
			environmentVariableName: "OPENCODE_API_KEY",
			matchUrl: "https://opencode.ai/zen/go/v1"
